'use strict';
// Verdant Ruins: 100 authored rescues in 10 connected chapters, following the old river map home.
// Same fields as story-desert.js.
(globalThis.RescueStories=globalThis.RescueStories||[])[4]={chapters:[
{title:'The River Market',arc:'The floating market at River Steps was trading when the river rose overnight. Its families were cut off on both banks.',levels:[
{n:'Thiago',r:'fruit boatman',t:'The market fire',s:'Thiago saw a cooking fire spread across two market boats. He pulled his family onto the top step, away from the smoke.',k:'found a jar on the steps',l:'My boat is full of mangoes and smoke. My family is full of air. Good trade.',x:'On the top step, someone left a sealed jar. Inside: a hand-drawn map of the whole river valley.',j:'A map in a jar.',m:'Someone wanted it found.',h:'smoke'},
{n:'Rosalía',r:'flower seller',t:'The lamp wire',s:'Rosalía sells orchids at the market. A lamp wire fell from the market poles into the shallow water by her stall.',k:'saw the map’s markings',l:'Orchids survive floods. Wires in water don’t forgive.',x:'The map marks every family’s house with a tiny drawing. My house has a flower on it.',j:'Every house.',m:'Someone knows every family here.',h:'cable'},
{n:'Benedito',r:'fisherman',t:'The rising river',s:'Benedito’s canoe was pulled loose by the rising river. He climbed the steps and is waiting at the top.',k:'knows how old the map is',l:'The river took my canoe. I let it. I can build another.',x:'The paper is new, but the drawings are copied from something very old. You can see the ghost lines.',j:'Copied from an old map.',m:'Who drew the first one?',h:'water'},
{n:'Benedita',r:'market cook',t:'The false boat',s:'Benedita got a message saying a rescue boat was waiting downstream. She called the market chief first and stayed on the steps.',k:'knows who sent the fake boat message',l:'Downstream was the flood. Up here was dry. Simple choice.',x:'The message came from a land company that wants families to leave the valley for good.',j:'They want the valley empty.',m:'Then we bring everyone home.',h:'radio'},
{n:'Aurélio',r:'market treasurer',t:'The co-op account',s:'Aurélio refused to give the market co-op’s bank PIN to a caller promising flood relief.',k:'saw the land company’s offer',l:'This money belongs to forty families. A phone call doesn’t get it.',x:'The land company offered to buy every flooded house. Cheap. They said nobody would ever find their way back.',j:'Nobody would find their way back.',m:'Unless they have the map.',h:'code'},
{n:'Dona Ivone',r:'herbalist',t:'The medicine boat',s:'Dona Ivone sealed the market’s medicines in a dry box for the riverside home.',k:'recognizes the map’s symbols',l:'Herbs can wait. Real medicines need doctors. This box goes to them.',x:'The symbols on the map are the old valley signs: a leaf for safe, a wave for danger, a heart for home.',j:'A heart for home.',m:'Like Dad’s sticker.',h:'medicine',sup:1},
{n:'Kauã',r:'student',t:'The jetty rail',s:'Kauã, 10, watched his sandal float away from the jetty. He stayed behind the rail instead of jumping in.',k:'followed the map’s heart',l:'The river can have my sandal. It can’t have me.',x:'The heart on the map is drawn on a house by the river. The riverside home.',j:'The riverside home.',m:'That’s where we’re going.',h:'gate'},
{n:'Lígia',r:'ferry pilot',t:'The ford',s:'Lígia could have driven her truck through the flooded ford. She turned around and waited at the steps.',k:'saw the map’s safe routes',l:'A ford in flood is a river with a road underneath. I chose the steps.',x:'The map has dotted paths marked with leaves. Every one avoids the flooded fords.',j:'Safe paths.',m:'Someone planned this.',h:'crossing'},
{n:'Raimundo',r:'boatbuilder',t:'The painted post',s:'Raimundo got lost in the rain and waited by the painted mooring post, the market’s meeting landmark.',k:'knows where the map came from',l:'That post has been painted by every generation. I sat on it like a child.',x:'The jar was left at dawn by a young man in a garage jacket. He drove off in a red truck.',j:'A red truck.',m:'…Jun?',h:'landmark'},
{n:'Mãe Benta',r:'market elder',t:'Last boat in',s:'Mãe Benta has run the River Market for fifty years. She won’t leave until every family is safely ashore.',k:'kept the map safe',l:'Fifty years of market days. Every family went home today.',j:'Last one at River Steps.',m:'And the map.',h:'verify'}]},
{title:'The Weavers',arc:'Moss Gate is a village of basket weavers whose painted stones mark every path. The flood cut the village in half.',levels:[
{n:'Iracema',r:'basket weaver',t:'The drying shed',s:'Iracema got the weavers out when the drying shed’s smoke fire got out of control.',k:'saw the painted stones',l:'Fifty baskets in that shed. I chose the fifty weavers.',x:'The Moss Gate stones are painted with the same symbols as the map. Leaf, wave, heart.',j:'Same symbols.',m:'The map and the village speak the same language.',h:'smoke'},
{n:'Caetano',r:'stone painter',t:'The gate wire',s:'Caetano is stuck behind a power wire that fell across the moss-covered gate.',k:'repaints the stones every year',l:'I paint stones. I don’t touch wires.',x:'Every year I repaint the stones. Someone always leaves fresh paint at the gate first.',j:'Someone helps.',m:'Who?',h:'cable'},
{n:'Moema',r:'weaver',t:'The flooded path',s:'Moema waited on the high side of the gate when the path below flooded.',k:'saw who left the paint',l:'The path will come back. So will I.',x:'The paint was left by a young man who arrived in a red truck from very far away.',j:'From far away.',m:'From Desert County?',h:'water'},
{n:'Jurema',r:'weaver',t:'The fake road',s:'Jurema got a message saying the land company had opened a new road out of the valley. She checked with the elders and stayed.',k:'knows where the fake road led',l:'There’s no new road. There’s only the old paths.',x:'The fake road led to the land company’s office. They wanted families to sign away their houses.',j:'Sign away their houses.',m:'Not today.',h:'radio'},
{n:'Anselmo',r:'village secretary',t:'The house deeds',s:'Anselmo refused to give the deed archive password to a man claiming to be from the land registry.',k:'saw the map in the archive',l:'Those deeds are every family’s home on paper. They stay locked.',x:'In the archive is an older map, two hundred years old. The new map copies it exactly.',j:'Two hundred years.',m:'Families rebuilt here before.',h:'code'},
{n:'Nurse Cida',r:'village nurse',t:'The weaver’s kit',s:'Nurse Cida sealed the village’s cuts-and-fever kit for the riverside home.',k:'treated the young man in the red truck',l:'Weavers cut their hands every day. I keep them stitched.',x:'The young man had a bandaged hand. He said, “I’ve been driving for a long time.”',j:'Driving for a long time.',m:'Since Desert County.',h:'medicine',sup:1},
{n:'Piatã',r:'student',t:'The mill pond',s:'Piatã, 9, stayed behind the mill pond fence when his woven ball rolled in.',k:'got a painted stone from the young man',l:'The ball floats. I don’t need to.',x:'The young man gave me a stone painted with a heart. He said, “Hearts mean home.”',j:'Hearts mean home.',m:'Jun used to say that.',h:'gate'},
{n:'Tainá',r:'weaver',t:'The muddy slope',s:'Tainá could have taken the shortcut down the muddy slope. She heard it rumble and turned back.',k:'saw the young man painting',l:'That slope moved while I watched. I’m glad I wasn’t on it.',x:'The young man was painting a leaf on every safe stone. He kept looking at a notebook.',j:'A notebook.',m:'Jun always carries a notebook.',h:'mudslide'},
{n:'Ubirajara',r:'weaver',t:'The great basket',s:'Ubirajara got lost in the rain and waited under the great hanging basket, the village landmark.',k:'saw the young man’s notebook',l:'The great basket holds a hundred years of weaving. Tonight it held me.',x:'The notebook had names. Hundreds of them. With dates and places.',j:'Hundreds of names.',m:'People we’ve rescued?',h:'landmark'},
{n:'Avó Jacira',r:'village elder',t:'Gate closed',s:'Avó Jacira won’t leave Moss Gate until every weaver is on the dry side.',k:'knows what the stones mean',l:'Every weaver safe. The gate closes for the night.',j:'Last one at Moss Gate.',m:'And the stones.',h:'verify'}]},
{title:'The Pilgrims',arc:'Temple Road leads to the old ruins where the valley’s elders walk each year. The flood stranded the pilgrims along the way.',levels:[
{n:'Grandfather Bao Long',r:'pilgrim',t:'The incense shelter',s:'Grandfather Bao Long got the pilgrims out of the shrine shelter when incense smoke filled it in the rain.',k:'knows who drew the first map',l:'Eighty years of pilgrimages. The road taught me patience.',x:'The elders say the first map was drawn by families who rebuilt after the great flood, long ago.',j:'After another flood.',m:'They came back too.',h:'smoke'},
{n:'Sister Amparo',r:'pilgrim guide',t:'The shrine wire',s:'Sister Amparo is stuck behind a shrine lamp wire that fell across Temple Road.',k:'read the ruins’ carvings',l:'I guide pilgrims. Tonight they guided me around a wire.',x:'The ruins have carvings of families carrying maps home. Each map has a heart.',j:'Families carrying maps home.',m:'That’s us.',h:'cable'},
{n:'Old Sebastião',r:'pilgrim',t:'The flooded road',s:'Old Sebastião waited on the temple steps when floodwater covered the road behind him.',k:'remembers the last great flood',l:'I’ve seen the river rise four times. It always falls.',x:'In the last great flood, families used the old map to find each other. Nobody was lost.',j:'Nobody was lost.',m:'Then we do it again.',h:'water'},
{n:'Naiara',r:'pilgrim',t:'The fake shuttle',s:'Naiara got a message that a land company shuttle would take pilgrims out of the valley. She asked the elders first and stayed.',k:'knows why the land company wants the ruins',l:'Pilgrims walk. We don’t board strange buses.',x:'The land company wants to build a resort on the ruins. They need the valley emptied.',j:'A resort on the ruins.',m:'Over our homes.',h:'radio'},
{n:'Venerable Thich An',r:'temple keeper',t:'The temple archive',s:'Venerable Thich An refused to give the temple archive key code to a man claiming to be a historian.',k:'keeps a copy of the old map',l:'The archive holds the valley’s memory. It is not for sale.',x:'The temple holds the original map. Someone came last month to copy it. A young man with a notebook.',j:'He copied the map.',m:'Then left it in a jar for us.',h:'code'},
{n:'Brother Lucas',r:'temple healer',t:'The pilgrims’ medicine',s:'Brother Lucas sealed the pilgrims’ heart and blood-pressure medicines for the riverside home.',k:'met the young man',l:'Old pilgrims carry old hearts. I carry their medicines.',x:'The young man said: “My sister rescues people. I map them so nobody gets lost again.”',j:'My sister rescues people.',m:'Jun.',h:'medicine',sup:1},
{n:'Mai',r:'student',t:'The lotus pond',s:'Mai, 7, on her first pilgrimage, stayed behind the lotus pond fence when her lantern floated away.',k:'got a lantern from the young man',l:'The lantern is swimming. I’m walking.',x:'The young man gave me a paper lantern with a heart on it. He said, “For the walk home.”',j:'For the walk home.',m:'He’s leaving hearts everywhere.',h:'gate'},
{n:'Damião',r:'pilgrim',t:'The ruin stairs',s:'Damião could have climbed the crumbling ruin stairs to see over the flood. He waited at the bottom.',k:'saw the red truck at the ruins',l:'Those stairs are a thousand years old. They don’t need me on them.',x:'The red truck was parked at the ruins at dawn. A young man was asleep in the cab.',j:'Asleep in the truck.',m:'He’s been driving all night.',h:'rockfall'},
{n:'Aunt Hoa',r:'pilgrim',t:'The stone lion',s:'Aunt Hoa got lost in the rain and waited by the stone lion, the pilgrims’ meeting landmark.',k:'knows what the young man said',l:'The lion has guarded this road for centuries. Tonight it guarded me.',x:'He said: “Every person my sister saves, I write down. Then I draw them home.”',j:'He draws them home.',m:'Jun…',h:'landmark'},
{n:'Grandmother Xuan',r:'pilgrimage leader',t:'Pilgrims home',s:'Grandmother Xuan leads the Temple Road pilgrimage. She won’t leave until every pilgrim is safe.',k:'knows the map’s history',l:'Every pilgrim found. The road is quiet now.',j:'Last one on Temple Road.',m:'And the map’s history.',h:'verify'}]},
{title:'Treehouse Camp',arc:'Canopy Camp is a summer camp built in the trees. When the flood came, the campers were scattered across the treehouses.',levels:[
{n:'Counselor Bia',r:'camp counselor',t:'The cook hut',s:'Counselor Bia got the campers out of the cook hut when the stove smoked in the rain.',k:'saw a child drawing on the map',l:'Twenty campers, twenty flashlights, one counselor. We did it.',x:'A camper found the river map and drew her own treehouse on it in orange crayon.',j:'In crayon.',m:'She wanted to be on the map too.',h:'smoke'},
{n:'Kawan',r:'student',t:'The zipline',s:'Kawan, 13, is stuck in a treehouse after a zipline’s power cable fell across the ladder.',k:'knows who drew in crayon',l:'I love the zipline. I don’t love live wires.',x:'The crayon drawing was by Yara, 6. She drew herself holding hands with “the hero.”',j:'The hero.',m:'That’s you, Jun.',h:'cable'},
{n:'Counselor Rafael',r:'camp counselor',t:'The flooded clearing',s:'Counselor Rafael moved his campers into the highest treehouse when the clearing flooded.',k:'saw the map’s new names',l:'The clearing became a lake. The treehouse became an island.',x:'The map has new names written beside the houses. Names of people rescued in other places.',j:'Other places.',m:'Desert County. Frostbite Pass.',h:'water'},
{n:'Mirela',r:'camp director',t:'The fake pickup',s:'Mirela got a message that parents should collect campers at the land company office. She called every parent first.',k:'knows why the land company wanted campers',l:'Parents pick up at camp. Always. No exceptions.',x:'The land company wanted photos of empty camps to prove the valley was abandoned.',j:'It’s not abandoned.',m:'It’s full of people.',h:'radio'},
{n:'Gustavo',r:'camp IT',t:'The parent list',s:'Gustavo refused to give the camp’s parent contact list password to a caller claiming to be the district.',k:'saw the young man’s visit',l:'Every parent’s number is in that list. It stays locked.',x:'The young man visited the camp last week. He asked every child where their home was.',j:'He mapped the campers.',m:'So they can get home.',h:'code'},
{n:'Nurse Ana Paula',r:'camp nurse',t:'The allergy kit',s:'Nurse Ana Paula sealed the campers’ allergy and asthma medicines for the riverside home.',k:'treated a homesick camper',l:'Bee stings, scraped knees, homesickness. I treat all three.',x:'A homesick camper stopped crying when she saw her house on the map. “I can find my way back,” she said.',j:'The map made her brave.',m:'Maps make people brave.',h:'medicine',sup:1},
{n:'Yara',r:'student',t:'The orange crayon',s:'Yara, 6, the camper who drew on the map, stayed behind the creek fence when her crayon fell in.',k:'drew the hero on the map',l:'I drew you on the map. You’re the hero. You came.',x:'I drew the hero. Then I drew a red truck and a boy with a notebook.',j:'A boy with a notebook.',m:'You’re on the map too, Jun.',h:'gate'},
{n:'Counselor Davi Lima',r:'camp counselor',t:'The rope bridge',s:'Counselor Davi Lima could have crossed the swaying rope bridge in the storm. He kept his campers on the platform.',k:'saw the second map',l:'Rope bridges are fun on sunny days. Today wasn’t one.',x:'Behind the camp, someone pinned a second map. It shows rescues far beyond this valley.',j:'A second map.',m:'Every rescue we’ve made.',h:'crossing'},
{n:'Pedrinho',r:'student',t:'The tallest tree',s:'Pedrinho, 11, got lost in the rain and waited at the tallest tree, the camp’s meeting point.',k:'saw the young man’s red truck',l:'The tallest tree is easy to find. That’s the point.',x:'The red truck was parked by the camp gate with a sticker on it: a wrench inside a heart.',j:'Dad’s sticker.',m:'Dad’s garage.',h:'landmark'},
{n:'Tia Lourdes',r:'camp founder',t:'Lights out',s:'Tia Lourdes founded Canopy Camp. She won’t leave until every camper is with family.',k:'kept the crayon map',l:'Thirty summers of campers. All home tonight.',j:'Last one at Canopy Camp.',m:'And the crayon map.',h:'verify'}]},
{title:'The Stone School',arc:'The Stone School sits on a hill above the flooded valley. Its teachers turned it into a shelter for the children.',levels:[
{n:'Professor Elis',r:'teacher',t:'The science lab',s:'Professor Elis got the children out of the science lab when a heater smoked in the damp.',k:'planned walking routes from the map',l:'I teach science. Today I taught evacuation.',x:'The teacher planned every safe walking route home from the river map. Each path has a leaf.',j:'Every route planned.',m:'Every child gets home.',h:'smoke'},
{n:'Akira',r:'student',t:'The playground wire',s:'Akira, 12, is waiting with friends behind a playground light wire that fell in the rain.',k:'learned the map’s routes',l:'We learned the routes like a song. Leaf, leaf, wave, home.',x:'Professor Elis made us memorize the routes: three leaves to the riverside home.',j:'Three leaves.',m:'The way home.',h:'cable'},
{n:'Professor Teodoro',r:'teacher',t:'The flooded basement',s:'Professor Teodoro brought the children upstairs when the school basement flooded.',k:'saw who brought the map',l:'Water in the basement, children in the attic. A good trade.',x:'A young man brought the map to the school. He said, “Teach them the way home.”',j:'Teach them the way home.',m:'Jun’s idea.',h:'water'},
{n:'Laís',r:'student',t:'The fake bus',s:'Laís, 14, got a message that a land company bus would take students home. She asked her teacher first and stayed.',k:'knows what the land company wanted',l:'Our teacher takes us home. Not a stranger’s bus.',x:'The land company wanted to close the school so families couldn’t return.',j:'No school, no families.',m:'The school stays.',h:'radio'},
{n:'Diretor Wagner',r:'headteacher',t:'The student records',s:'Diretor Wagner refused to give the student records password to someone claiming to be the ministry.',k:'kept the map’s copy',l:'Every child’s details are in there. They stay private.',x:'The school keeps a copy of the map in the safe. Next to it, a letter from Desert County.',j:'A letter from Desert County.',m:'From the garage?',h:'code'},
{n:'Nurse Fabiana',r:'school nurse',t:'The school medicines',s:'Nurse Fabiana sealed the school’s asthma and epilepsy medicines for the riverside home.',k:'read the Desert County letter',l:'Two hundred children, two hundred medicine plans. All sealed.',x:'The letter said: “I’m Jun. My sister rescues people. I’ll map every family so nobody is lost.”',j:'You read my letter?',m:'Jun. You did all this?',h:'medicine',sup:1},
{n:'Bento',r:'student',t:'The rain barrel',s:'Bento, 8, stayed back from the overflowing rain barrel when his paper boat sailed in.',k:'learned to read the map',l:'My boat sailed away. I stayed on the hill.',x:'I can read the map now. Leaf is safe, wave is danger, heart is home.',j:'He learned it.',m:'Every child learned it.',h:'gate'},
{n:'Professor Marta',r:'teacher',t:'The hillside path',s:'Professor Marta could have taken the slippery hillside path. She heard it rumble and took the long way.',k:'saw the aqueduct on the map',l:'The hillside moved while I watched. The long way is the right way.',x:'The map has the Broken Aqueduct crossed out. Someone knew it would fail before it did.',j:'Crossed out.',m:'Someone knew.',h:'mudslide'},
{n:'Heitor',r:'student',t:'The school bell',s:'Heitor, 10, got lost in the rain and waited under the school bell, the meeting point.',k:'knows who crossed out the aqueduct',l:'The bell is loud. I stayed under it so they’d find me.',x:'The young man crossed out the aqueduct. He said the engineers told him it was cracked.',j:'He asked the engineers.',m:'He did his homework.',h:'landmark'},
{n:'Dona Celeste',r:'school founder',t:'School closed',s:'Dona Celeste founded the Stone School. She won’t leave until every child is home.',k:'knows who planned the routes',l:'Every child home. The school can rest.',j:'Last one at the Stone School.',m:'And the routes.',h:'verify'}]},
{title:'The Water Keepers',arc:'The Broken Aqueduct once carried water to the whole valley. Its keepers knew it would fail, and stayed to warn everyone.',levels:[
{n:'Engenheiro Otávio',r:'water engineer',t:'The pump house',s:'Engenheiro Otávio got his crew out of the pump house when the motor smoked in the flood.',k:'warned that the aqueduct would fail',l:'I warned them for ten years. Tonight it fell. Everyone was clear.',x:'The aqueduct is crossed out on the map. Someone knew it would fail.',j:'You warned them.',m:'And Jun listened.',h:'smoke'},
{n:'Jandira',r:'water keeper',t:'The sluice wire',s:'Jandira is stuck behind a sluice gate power wire that fell in the flood.',k:'talked to the young man with the notebook',l:'I keep the water moving. Tonight I let it go.',x:'A young man asked me which parts of the aqueduct were safe. He wrote everything down.',j:'He wrote it down.',m:'Jun writes everything down.',h:'cable'},
{n:'Cícero',r:'canal worker',t:'The overflow',s:'Cícero waited on the aqueduct’s high wall when the overflow channel flooded.',k:'saw the aqueduct fall',l:'The aqueduct fell like a tired giant. Nobody was under it.',x:'It fell exactly where the map said. Not one person was on that road.',j:'Nobody hurt.',m:'Because of the map.',h:'water'},
{n:'Dalva',r:'water clerk',t:'The fake repair',s:'Dalva got an order saying the aqueduct had been repaired and the road was open. She checked with the engineer and stayed.',k:'knows who faked the repair notice',l:'You don’t repair an aqueduct overnight. I know because I file the paperwork.',x:'The land company faked it. They wanted people on the road when it fell, to scare everyone away.',j:'They wanted people hurt?',m:'They wanted people gone.',h:'radio'},
{n:'Severino',r:'aqueduct guard',t:'The control room',s:'Severino refused to give the aqueduct control room code to a man claiming to be a repair contractor.',k:'saw the second map',l:'Those controls move a river. They stay locked.',x:'In the control room, someone pinned a second map: every rescue, all the way from Desert County.',j:'The second map.',m:'Jun’s been mapping since the first night.',h:'code'},
{n:'Dra. Ceci',r:'valley doctor',t:'The waterborne kit',s:'Dra. Ceci sealed the water-purifying tablets and fever medicines for the riverside home.',k:'treated the young man',l:'Flood water carries sickness. I carry the cure.',x:'The young man had a fever from driving in the rain. He said, “I can’t stop. My sister is still out there.”',j:'I was sick?',m:'You never told me.',h:'medicine',sup:1},
{n:'Zé',r:'student',t:'The canal edge',s:'Zé, 11, stayed back from the canal edge when his football rolled into the fast water.',k:'saw the red truck leave',l:'Football’s gone. I’m still here. Mom will be happy.',x:'The red truck drove toward the Garden Wall. The boy in it waved at me.',j:'I waved.',m:'You always wave.',h:'gate'},
{n:'Raquel',r:'farmer',t:'The aqueduct road',s:'Raquel could have driven the aqueduct road before it fell. She took the map’s leaf route instead.',k:'followed the map home',l:'The map said leaf. I followed the leaf. I’m alive.',x:'I followed the leaves on the map. They took me around the aqueduct, safe.',j:'The map worked.',m:'Jun’s map saved her.',h:'crossing'},
{n:'Josué',r:'water keeper',t:'The arch',s:'Josué got lost in the rain and waited under the last standing arch, the keepers’ meeting point.',k:'knows where the second map leads',l:'The arch is the last piece of the aqueduct. I stayed with it.',x:'The second map ends at the riverside home. Every rescue line goes there.',j:'Everyone goes there.',m:'Everyone we saved.',h:'landmark'},
{n:'Mestre Gonçalo',r:'aqueduct master',t:'The aqueduct falls',s:'Mestre Gonçalo kept the aqueduct for forty years. He won’t leave until every keeper is clear.',k:'knows who crossed it out',l:'Forty years I kept it. Tonight I let it fall, and kept the people instead.',j:'Last one at the Broken Aqueduct.',m:'And the warning.',h:'verify'}]},
{title:'The Gardeners',arc:'The Garden Wall surrounds the valley’s community garden. The gardeners were harvesting when the flood trapped them inside the walls.',levels:[
{n:'Dona Graça',r:'gardener',t:'The compost fire',s:'Dona Graça got the gardeners out when the compost heap started smoking in the heat.',k:'found a second map behind the wall',l:'Compost burns. Gardeners don’t. Not on my watch.',x:'Pinned behind the compost shed: a big sheet of paper covered in lines, starting from a garage in the desert.',j:'Lines from the desert.',m:'You mapped every one, Jun.',h:'smoke'},
{n:'Severina',r:'beekeeper',t:'The greenhouse wire',s:'Severina is stuck behind a greenhouse lamp wire that fell across the garden path.',k:'read the second map',l:'My bees know when to stay home. I should learn from them.',x:'The second map shows Dad’s porch light, the White Beacon, the harbor clinic, Truck 7.',j:'Everything.',m:'Our whole journey.',h:'cable'},
{n:'Lauro',r:'gardener',t:'The flooded beds',s:'Lauro waited on the garden wall when the vegetable beds flooded.',k:'saw the names on the second map',l:'The lettuce is swimming. I’m sitting on a wall.',x:'The second map has names: Lucía, Katya, Amaya, Marisol. Hundreds of them.',j:'Hundreds of names.',m:'Five hundred.',h:'water'},
{n:'Cleide',r:'garden organizer',t:'The fake sale',s:'Cleide got a message that the garden had been sold to the land company. She checked with the council and stayed.',k:'knows the garden is safe',l:'This garden belongs to the valley. Not to a company.',x:'The council said the land company’s deal fell through. Too many families came home.',j:'Too many families came home.',m:'Because of the map.',h:'radio'},
{n:'Gilberto',r:'garden treasurer',t:'The seed fund',s:'Gilberto refused to give the seed fund’s PIN to a caller promising flood grants.',k:'met the young man',l:'The seed fund grows the whole valley’s food. Nobody steals seeds.',x:'The young man pinned the map and said, “My sister will come here. Show her this.”',j:'I asked them to show you.',m:'You planned this.',h:'code'},
{n:'Nurse Rita',r:'garden nurse',t:'The garden kit',s:'Nurse Rita sealed the garden’s bee-sting and cut kit for the riverside home.',k:'treated the young man’s hand',l:'Gardeners cut, sting and scrape. I keep them growing.',x:'His hand was bandaged from fixing the red truck. He said, “Dad taught me. Badly.”',j:'Dad did teach me badly.',m:'He taught you enough.',h:'medicine',sup:1},
{n:'Ritinha',r:'student',t:'The lily pond',s:'Ritinha, 9, stayed behind the lily pond fence when her watering can fell in.',k:'saw the young man writing',l:'The can floats. I water plants, not ponds.',x:'He wrote my name on the map. He said, “Now you’re part of the story.”',j:'Part of the story.',m:'Everyone is.',h:'gate'},
{n:'Osvaldo',r:'gardener',t:'The slipping bank',s:'Osvaldo could have climbed down the muddy bank to save his tools. He heard it rumble and stayed.',k:'saw where the red truck went',l:'Tools can be bought. The bank moved two meters.',x:'The red truck drove to Green Bridge. The young man was carrying a parcel.',j:'A parcel.',m:'From Desert County?',h:'mudslide'},
{n:'Dorinha',r:'gardener',t:'The scarecrow',s:'Dorinha got lost in the rain and waited by the big scarecrow, the gardeners’ meeting point.',k:'knows what the second map ends with',l:'The scarecrow has stood here thirty years. He doesn’t scare me.',x:'At the end of the second map is a heart and three words: “Nobody drives alone.”',j:'Nobody drives alone.',m:'That’s our promise.',h:'landmark'},
{n:'Seu Joaquim',r:'garden elder',t:'Gates shut',s:'Seu Joaquim has kept the community garden for fifty years. He won’t leave until every gardener is safe.',k:'kept the second map safe',l:'Fifty harvests. Tonight, I harvested people.',j:'Last one at the Garden Wall.',m:'And the second map.',h:'verify'}]},
{title:'The River Post',arc:'The Green Bridge post office runs mail boats up and down the valley. When the flood came, the post boats were stranded.',levels:[
{n:'Carteiro Edson',r:'mail boatman',t:'The mail boat',s:'Carteiro Edson got his passengers off the mail boat when its engine smoked.',k:'delivered a parcel from Desert County',l:'Thirty years of mail. Never lost a letter. Never lost a passenger.',x:'The bridge keeper says the second map was mailed from a garage in Desert County.',j:'From our garage.',m:'You mailed it ahead.',h:'smoke'},
{n:'Marlene',r:'post clerk',t:'The bridge cable',s:'Marlene is stuck behind a power cable that fell across the Green Bridge.',k:'stamped the Desert County parcel',l:'I stamp parcels. I don’t stamp on cables.',x:'The parcel was stamped from Desert County, eight weeks ago. Sender: “Jun, the garage.”',j:'Eight weeks ago.',m:'Before we even started.',h:'cable'},
{n:'Geraldo',r:'bridge keeper',t:'The flooded underpass',s:'Geraldo waited on the bridge deck when the underpass flooded.',k:'knows what Jun asked',l:'I keep the bridge. Tonight it kept me.',x:'Jun asked me: “When my sister crosses, tell her I’m at Hidden Dock.”',j:'I’m at Hidden Dock.',m:'Then that’s where we go.',h:'water'},
{n:'Sandra',r:'post manager',t:'The fake redirect',s:'Sandra got an order to redirect all valley mail to the land company. She refused without a signed form.',k:'knows why the mail was redirected',l:'Mail goes to the people it’s addressed to. Always.',x:'The land company wanted the families’ letters so they couldn’t find each other.',j:'They wanted to separate families.',m:'We’re reuniting them.',h:'radio'},
{n:'Wellington',r:'post IT',t:'The tracking system',s:'Wellington refused to give the parcel tracking password to a caller claiming to be the post headquarters.',k:'tracked Jun’s parcels',l:'Every parcel in this valley is tracked. By me. Not by strangers.',x:'Jun sent parcels to every world: a map to the White Beacon, the harbor clinic, the workshop.',j:'I sent maps everywhere.',m:'So everyone could find each other.',h:'code'},
{n:'Dra. Lúcia',r:'river doctor',t:'The post boat kit',s:'Dra. Lúcia sealed the post boat’s medical kit for the riverside home.',k:'treated Jun’s fever',l:'The river doctor rides the mail boat. Today the mail boat rode me.',x:'Jun had a fever and wouldn’t rest. He said: “Not until everyone is on the map.”',j:'I was stubborn.',m:'You’re a Reyes.',h:'medicine',sup:1},
{n:'Gabriel',r:'student',t:'The bridge rail',s:'Gabriel, 12, stayed behind the bridge rail when his letter blew into the river.',k:'got a letter from Jun',l:'The letter flew away. The words are still in my head.',x:'Jun wrote me: “My sister is coming. She saves everyone. Wait for her.”',j:'I told them you’d come.',m:'And I did.',h:'gate'},
{n:'Neide',r:'post boat captain',t:'The river crossing',s:'Neide could have taken her post boat across the flooded river. She moored and waited.',k:'saw Jun at Hidden Dock',l:'The river is angry. I let it be angry without me.',x:'Jun is at Hidden Dock, sitting on the red truck’s hood with his notebook.',j:'I’m waiting.',m:'We’re coming.',h:'tide'},
{n:'Valdir',r:'postman',t:'The green post box',s:'Valdir got lost in the rain and waited by the green post box, the valley’s meeting landmark.',k:'knows what Jun wrote last',l:'The post box has held a thousand letters. Tonight it held me up.',x:'Jun’s last letter: “Bring everyone home. I’ll have the map ready.”',j:'The map is ready.',m:'So are we.',h:'landmark'},
{n:'Dona Zuleica',r:'postmistress',t:'Last post',s:'Dona Zuleica has run the Green Bridge post office for forty years. She won’t leave until every letter carrier is safe.',k:'knows where the map was mailed from',l:'Forty years of letters. Tonight’s was the most important.',j:'Last one at Green Bridge.',m:'And the parcel.',h:'verify'}]},
{title:'The Boatbuilders',arc:'Hidden Dock is where the valley’s boatbuilders work out of sight of the river. Jun has been waiting there with the map.',levels:[
{n:'Mestre Antônio',r:'boatbuilder',t:'The tar pot',s:'Mestre Antônio got the boatbuilders out when the tar pot smoked in the boatyard.',k:'hosted Jun at the dock',l:'Sixty years building boats. Tonight I built a rescue line.',x:'Jun has been staying at the dock. He spends every night drawing your rescues on the map.',j:'Every night.',m:'Every rescue.',h:'smoke'},
{n:'Luana',r:'boat painter',t:'The slipway wire',s:'Luana is stuck behind a slipway lamp wire that fell in the rain.',k:'painted the red truck’s heart',l:'I paint boat names. Tonight I painted a truck.',x:'I repainted the wrench-and-heart on Jun’s red truck. He said it’s his dad’s garage sign.',j:'Dad’s sign.',m:'On your truck now.',h:'cable'},
{n:'Erasmo',r:'boatbuilder',t:'The rising dock',s:'Erasmo waited on the boat shed roof when the dock flooded.',k:'saw Jun’s map up close',l:'The river came into the dock. I went up to the roof.',x:'Jun’s map has five hundred names. Every one connected by a line to the riverside home.',j:'Five hundred.',m:'Five hundred people we brought home.',h:'water'},
{n:'Débora',r:'boatyard manager',t:'The fake buyer',s:'Débora got a message from a “buyer” asking the boatbuilders to bring their boats to the land company. She refused.',k:'knows the land company is finished',l:'Our boats float for families, not for companies.',x:'The land company is finished. Every family came home. There’s no empty valley to sell.',j:'They lost.',m:'Because nobody gave up.',h:'radio'},
{n:'Jonas Prado',r:'boatyard clerk',t:'The boat registry',s:'Jonas Prado refused to give the boat registry password to a caller pretending to be the river authority.',k:'knows what Jun admitted',l:'Every boat in the valley is in my registry. It stays private.',x:'Jun admitted it: he’s mapped every family you brought home since the first night in Desert County.',j:'Since the first night.',m:'Jun. You never stopped.',h:'code'},
{n:'Dra. Helena',r:'dock doctor',t:'The dock kit',s:'Dra. Helena sealed the boatyard’s medical kit for the riverside home.',k:'checked Jun’s health',l:'Boatbuilders are tough. Their splinters are tougher.',x:'Jun is tired but healthy. He said: “I just want to see everyone in one place.”',j:'Everyone in one place.',m:'Tonight.',h:'medicine',sup:1},
{n:'Tiago',r:'student',t:'The dock edge',s:'Tiago, 10, an apprentice, stayed back from the dock edge when his carving knife fell in.',k:'helped Jun draw the map',l:'Knives are sharp. Rivers are deep. I stayed back.',x:'I helped Jun color the map. He let me draw the porch light.',j:'You drew the porch light.',m:'Dad would love it.',h:'gate'},
{n:'Fátima',r:'boatbuilder',t:'The dock bridge',s:'Fátima could have crossed the flooded dock bridge. She waited for the water to drop.',k:'saw Jun waiting',l:'The bridge will dry. I waited.',x:'Jun is waiting at the end of the dock with the map rolled up under his arm.',j:'I’m here.',m:'We see you.',h:'crossing'},
{n:'Nestor',r:'boatbuilder',t:'The boat keel',s:'Nestor got lost in the dark and waited by the giant keel, the boatyard’s meeting landmark.',k:'knows what Jun will do next',l:'The keel is the spine of a boat. Tonight it was mine.',x:'Jun said: “Next we go to the riverside home. Everyone’s waiting.”',j:'Everyone’s waiting.',m:'Let’s go home.',h:'night'},
{n:'Dona Fé',r:'boatyard owner',t:'Hidden no more',s:'Dona Fé owns the boatyard. She won’t leave Hidden Dock until every builder is safe.',k:'knows what Jun confessed',l:'The dock is hidden no more. Everyone knows the way home now.',j:'Last one at Hidden Dock.',m:'And the confession.',h:'verify'}]},
{title:'Home',arc:'Home Road leads to the riverside home, where everyone you rescued across five worlds is gathering. The neighbors who opened the house still need a ride.',levels:[
{n:'Benício',r:'riverside cook',t:'The bonfire',s:'Benício was cooking for the homecoming when the welcome bonfire smoked in the damp. He moved the tables and the guests upwind.',k:'is cooking for five hundred guests',l:'Five hundred guests and one bonfire. I’ll cook on the stove like a sensible man.',x:'The riverside home is full of lights. People from every world are arriving on Home Road.',j:'Everyone came.',m:'Every single one.',h:'smoke'},
{n:'Iolanda',r:'neighbor',t:'The lantern wire',s:'Iolanda was stringing lanterns along Home Road when a wire came down in the rain. She’s waiting on the far side of it.',k:'hung a lantern from Frostbite Pass',l:'I hang lights for parties. Tonight a light nearly hung me. I stepped back.',x:'Henrik from the ski school brought Katya’s lantern down the mountain. It hangs over the riverside door.',j:'Katya’s lantern.',m:'Keep the room warm.',h:'cable'},
{n:'Joca',r:'river fisherman',t:'The river road',s:'Joca, the riverside home’s fisherman neighbor, waited on the high road when the river rose over the low one.',k:'met a baby born on the tide',l:'I’ve fished this river forty years. It still rises faster than I walk.',x:'Amaya came from Neon Harbor with baby Marea, asleep in a basket woven at Moss Gate.',j:'Marea!',m:'She’s getting big.',h:'water'},
{n:'Socorro',r:'neighbor',t:'The fake detour',s:'Socorro got a message saying Home Road was closed and guests should detour. She checked Jun’s map and stayed on the right route.',k:'found her own name on Jun’s map',l:'A message said turn back. The map said home. I trusted the map.',x:'Jun’s map is pinned to the riverside door. Every guest finds their own name on it.',j:'Every name.',m:'Every person.',h:'radio'},
{n:'Everton',r:'party organizer',t:'The guest list',s:'Everton refused to share the homecoming guest list with a stranger asking for everyone’s addresses.',k:'is keeping the guest list',l:'Five hundred names. Not one of them leaves this notebook.',x:'The guest list has five hundred names. Everyone you rescued, in five worlds.',j:'Five hundred.',m:'All here.',h:'code'},
{n:'Nurse Nilza',r:'valley nurse',t:'The homecoming kit',s:'Nurse Nilza sealed the homecoming first-aid kit and the elders’ medicines for the riverside home.',k:'saw Truck 7 arrive',l:'Five hundred guests means five hundred chances to trip. I came prepared.',x:'Marisol drove Truck 7 all the way from the Badlands. It’s parked in the garden with its lights on.',j:'Truck 7.',m:'Dad’s truck, home.',h:'medicine',sup:1},
{n:'Maria Flor',r:'student',t:'The flower crown',s:'Maria Flor, 7, stayed behind the riverbank fence when her flower crown floated away, and called for her grandmother.',k:'met an old dog on the road',l:'My crown is going on a boat trip. I’m staying for the party.',x:'An old dog followed the porch light all the way down Home Road. Her tag says “Lucky.”',j:'Lucky!',m:'Good girl. You found us.',h:'gate'},
{n:'Seu Ananias',r:'bridge neighbor',t:'The Home Road bridge',s:'Seu Ananias waited at the Home Road bridge instead of crossing in the flood, holding a lamp for the late guests.',k:'heard an old lullaby by the fire',l:'Eighty years by this bridge. Tonight it carried the whole world to my door.',x:'Katya sits by the fire and hums the shelter lullaby. Everyone hums along.',j:'The lullaby.',m:'Mom’s song.',h:'crossing'},
{n:'Tereza',r:'neighbor',t:'The mango tree',s:'Tereza got lost in the dark and waited under the big mango tree, the one landmark everyone on Home Road knows.',k:'saw who is on the porch',l:'That mango tree has fed this road for thirty years. Tonight it sheltered me.',x:'On the porch, Dad stands next to Jun, holding the door open.',j:'Dad.',m:'We’re home.',h:'landmark'},
{n:'Vó Aurora',r:'keeper of the riverside home',t:'Nobody drives alone',s:'Vó Aurora, Mom’s oldest friend, opened the riverside home to all five worlds. She’s waiting at the gate for the last ride in.',k:'knew Mom when she planted the mango tree',l:'Your mother planted that mango tree. Tonight everyone she loved is under it. Come in.',j:'Vó Aurora.',m:'Nobody drives home alone.',h:'verify'}]}
]};
